import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Host Setup Doctor & Wizard — Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-14-host-setup-doctor-design.md","filePath":"superpowers/specs/2026-09-14-host-setup-doctor-design.md","lastUpdated":1789418601000}'),s={name:"superpowers/specs/2026-09-14-host-setup-doctor-design.md"};function r(d,e,n,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="host-setup-doctor-wizard-—-design" tabindex="-1">Host Setup Doctor &amp; Wizard — Design <a class="header-anchor" href="#host-setup-doctor-wizard-—-design" aria-label="Permalink to &quot;Host Setup Doctor &amp; Wizard — Design&quot;">​</a></h1><p>Date: 2026-09-14 Status: Approved design, pending implementation plan</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Beholder assumes the Android SDK is already installed. <code>RealSdkRunner::discover()</code> looks in <code>ANDROID_HOME</code> → <code>ANDROID_SDK_ROOT</code> → <code>~/Library/Android/sdk</code> and returns terse errors when cmdline-tools or the emulator binary are missing. First-run users with nothing installed see raw failure strings, and manual bootstrap is fragile:</p><ul><li><code>avdmanager</code>/<code>sdkmanager</code> are Java wrappers; a GUI app inherits no shell environment, so <code>JAVA_HOME</code> is unset and the wrapper dies (<code>test: : integer expression expected</code>, then &quot;Unable to locate a Java Runtime&quot;).</li><li><code>sdkmanager --licenses</code> is deprecated and the tooling now warns toward the new <code>android</code> CLI.</li><li>Hardcoded cmdline-tools zip build numbers go stale.</li></ul><p>The Emulators view compounds this: an empty AVD list renders a single muted line (&quot;No AVDs found — create one below.&quot;) and a missing SDK renders as a raw error string.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>One-click, headless, in-app setup for a clean macOS machine: Android Studio (official installer), cmdline-tools, platform-tools, emulator — then hand off to the existing AVD creation flow.</li><li>A host doctor that always explains what is missing and what will be done about it.</li><li>Friendly, actionable empty states in the Emulators view.</li><li>No Homebrew dependency. All artifacts from official Google sources.</li></ul><h2 id="non-goals-v1" tabindex="-1">Non-goals (v1) <a class="header-anchor" href="#non-goals-v1" aria-label="Permalink to &quot;Non-goals (v1)&quot;">​</a></h2><ul><li>Managing the new <code>android</code> CLI (detect-and-prefer can come later; <code>sdkmanager</code>/<code>avdmanager</code> remain the stable path).</li><li>Installing system images or creating AVDs from the wizard (the existing EmulatorsView flow owns that).</li><li>Writing shell rc files without explicit user confirmation.</li><li>Linux/Windows support (macOS first; checks are structured so ports stay possible).</li></ul><h2 id="user-experience" tabindex="-1">User experience <a class="header-anchor" href="#user-experience" aria-label="Permalink to &quot;User experience&quot;">​</a></h2><h3 id="startup-gate" tabindex="-1">Startup gate <a class="header-anchor" href="#startup-gate" aria-label="Permalink to &quot;Startup gate&quot;">​</a></h3><p>On app start the frontend runs the host doctor silently:</p><ul><li>All hard checks pass → normal app; host doctor stays reachable from the Emulators view.</li><li>Any hard check fails → the app opens on the Setup screen.</li></ul><h3 id="setup-screen" tabindex="-1">Setup screen <a class="header-anchor" href="#setup-screen" aria-label="Permalink to &quot;Setup screen&quot;">​</a></h3><ul><li>Checklist mirroring the doctor checks with ok/warn/fail states (same <code>DoctorCheck</code> shape and styling as the existing <code>DoctorPanel</code>).</li><li>Primary button &quot;Set up everything&quot; runs all missing fixes in dependency order; each item also has an individual Fix button.</li><li>Long steps stream progress through the existing install-log channel (<code>installLog</code>). The Android Studio step warns about the ~2 GB download before starting.</li><li>Steps are idempotent and resumable: on failure the doctor re-detects and offers only what is missing.</li></ul><h3 id="emulators-empty-states" tabindex="-1">Emulators empty states <a class="header-anchor" href="#emulators-empty-states" aria-label="Permalink to &quot;Emulators empty states&quot;">​</a></h3><p>Three distinct states replace the current single muted line / raw error:</p><ol><li><strong>Host not ready</strong> (doctor reports hard failures): full-panel state — title &quot;Set up your Android environment&quot;, one-line explanation, a summary of the missing pieces, CTA &quot;Open setup&quot; navigating to the Setup screen. The raw error string is collapsed behind a &quot;Details&quot; disclosure.</li><li><strong>Host ready, zero AVDs</strong>: title &quot;No emulators yet&quot;, hint that Beholder applies the right image and settings automatically, CTA &quot;Create emulator&quot; scrolling to and focusing the existing create form.</li><li><strong>Unexpected error</strong> (host OK but a command failed): <code>ErrorBox</code> as today.</li></ol><h2 id="host-doctor-checks" tabindex="-1">Host doctor checks <a class="header-anchor" href="#host-doctor-checks" aria-label="Permalink to &quot;Host doctor checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>check</th><th>fails when</th><th>fix</th></tr></thead><tbody><tr><td><code>java</code></td><td>JDK 17+ resolvable</td><td>no source resolves</td><td><code>install_android_studio</code></td></tr><tr><td><code>android_studio</code></td><td><code>/Applications/Android Studio.app</code> exists</td><td>missing</td><td><code>install_android_studio</code></td></tr><tr><td><code>sdk_root</code></td><td>canonical SDK dir exists</td><td>missing</td><td><code>init_sdk_dir</code></td></tr><tr><td><code>cmdline_tools</code></td><td><code>$SDK/cmdline-tools/latest/bin</code> has <code>sdkmanager</code> + <code>avdmanager</code></td><td>missing</td><td><code>install_cmdline_tools</code></td></tr><tr><td><code>platform_tools</code></td><td><code>$SDK/platform-tools/adb</code> exists</td><td>missing</td><td><code>install_sdk_packages</code></td></tr><tr><td><code>emulator</code></td><td><code>$SDK/emulator/emulator</code> exists</td><td>missing</td><td><code>install_sdk_packages</code></td></tr><tr><td><code>avd_present</code></td><td>at least one AVD (soft: warn)</td><td>none</td><td>none — CTA to the create flow</td></tr><tr><td><code>env_consistency</code></td><td><code>ANDROID_HOME</code>/<code>ANDROID_SDK_ROOT</code> match reality (soft: warn)</td><td>mismatch or stale</td><td><code>write_shell_env</code> (optional)</td></tr></tbody></table><p><code>avd_present</code> and <code>env_consistency</code> are soft — they never gate the app.</p><h2 id="detection-rules" tabindex="-1">Detection rules <a class="header-anchor" href="#detection-rules" aria-label="Permalink to &quot;Detection rules&quot;">​</a></h2><ul><li>Java resolution order (first hit wins): Android Studio JBR (<code>/Applications/Android Studio.app/Contents/jbr/Contents/Home</code>) → <code>JAVA_HOME</code> → <code>/usr/libexec/java_home</code> → <code>java</code> on PATH.</li><li>The resolved Java home is injected as <code>JAVA_HOME</code> on every <code>sdkmanager</code>/<code>avdmanager</code> invocation. Required because GUI apps do not inherit shell environments; this eliminates the wrapper-crash class seen in manual bootstrap.</li><li>SDK root resolution order is unchanged from <code>RealSdkRunner::discover</code>.</li></ul><h2 id="bootstrap-steps-fix-actions" tabindex="-1">Bootstrap steps (fix actions) <a class="header-anchor" href="#bootstrap-steps-fix-actions" aria-label="Permalink to &quot;Bootstrap steps (fix actions)&quot;">​</a></h2><ol><li><code>install_android_studio</code>: resolve the current official dmg URL, download, <code>hdiutil attach</code>, copy <code>Android Studio.app</code> to <code>/Applications</code>, detach. Skipped when already present.</li><li><code>init_sdk_dir</code>: <code>mkdir -p ~/Library/Android/sdk</code>.</li><li><code>install_cmdline_tools</code>: resolve the current official cmdline-tools mac zip from Google&#39;s repository index XML, unpack into <code>$SDK/cmdline-tools/latest</code> (canonical layout — Android Studio finds it too).</li><li><code>install_sdk_packages</code>: with <code>JAVA_HOME</code> = Studio JBR, run <code>sdkmanager platform-tools emulator</code>, then accept licenses.</li><li><code>write_shell_env</code> (only on explicit consent): append the <code>ANDROID_HOME</code> export to <code>~/.zshrc</code> after showing the exact lines.</li></ol><p>No Homebrew anywhere.</p><h3 id="implementation-time-verification-items-prove-with-curl-before-coding" tabindex="-1">Implementation-time verification items (prove with curl before coding) <a class="header-anchor" href="#implementation-time-verification-items-prove-with-curl-before-coding" aria-label="Permalink to &quot;Implementation-time verification items (prove with curl before coding)&quot;">​</a></h3><ul><li>The stable endpoint used to resolve the latest official Studio dmg URL (official metadata vs. downloads page — pick with evidence).</li><li>The current version of the dl.google.com repository index XML used to resolve the cmdline-tools zip URL.</li><li>The JBR copied from the dmg runs without a Gatekeeper prompt (expected to pass via Google&#39;s notarization; if not, document a consented <code>xattr -dr com.apple.quarantine</code> fallback).</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><code>crates/bh-device/src/host_doctor.rs</code> — pure checks over injectable base paths (tempdir-testable), returning <code>HostCheck</code> with the same shape as the existing device <code>DoctorCheck</code>.</li><li><code>crates/bh-device/src/host_bootstrap.rs</code> — fix actions as functions over a small command-runner trait with a fake for tests; reuse <code>DeviceError</code>.</li><li><code>RealSdkRunner::run</code> gains per-invocation <code>JAVA_HOME</code> injection.</li><li>Tauri commands: <code>run_host_doctor()</code> returns checks; <code>apply_host_fix(fix)</code> streams via the existing install-log channel.</li><li>Frontend: <code>SetupView</code> (checklist + actions), startup gate in <code>App</code>, and the EmulatorsView empty states. Reuse <code>DoctorPanel</code> styling; no new UI primitives.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li>Rust: checks as pure functions over tempdirs (JBR present/absent, SDK layouts, stale env vars); bootstrap steps against a fake runner asserting command, args, and injected env; step idempotency.</li><li>Frontend (vitest): startup gate routing on doctor results; EmulatorsView renders the setup CTA vs. create-first-AVD CTA vs. <code>ErrorBox</code>.</li></ul><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><ul><li>Google endpoints for &quot;latest&quot; URLs change shape → mitigated by resolving from official metadata at runtime, the verification items above, and clear failure text with a manual-download fallback link in the UI.</li><li>Android Studio download size (~2 GB) → explicit warning and streamed progress.</li><li>Deprecated-tooling warnings from <code>sdkmanager</code> are noisy → routed to the log channel, never surfaced as errors.</li></ul>',35)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
